//! Differential fixtures generated by the unmodified Python geometry functions.
use serde::Deserialize;
use sleufbase_rust::{
    marxact::centerline,
    marxact_alignment::{apply_rotation, recalculate},
    model::Vertex,
    project::{read_project, save_project, NativeProject},
    virtual_trench::{TrenchPoint, VirtualTrench},
};

#[derive(Deserialize)]
struct Manual {
    degrees: f64,
    expected: ([Option<f64>; 3], [Option<f64>; 3], f64),
}
#[derive(Deserialize)]
struct Case {
    name: String,
    polygon: Vec<[Option<f64>; 3]>,
    objects: Vec<[Option<f64>; 3]>,
    automatic: ([Option<f64>; 3], [Option<f64>; 3], f64),
    manual: Vec<Manual>,
}

fn vertex(p: &[Option<f64>; 3]) -> Vertex {
    Vertex {
        x: p[0].unwrap(),
        y: p[1].unwrap(),
        z: p[2],
    }
}
fn close(a: f64, b: f64) {
    assert!((a - b).abs() < 1e-7, "{a} != {b}");
}
fn same_vertex(a: Vertex, b: Vertex) {
    close(a.x, b.x);
    close(a.y, b.y);
    match (a.z, b.z) {
        (Some(x), Some(y)) => close(x, y),
        (None, None) => {}
        _ => panic!("Z mismatch: {a:?}, {b:?}"),
    }
}
fn cases() -> Vec<Case> {
    serde_json::from_str(include_str!("fixtures/marxact_alignment.json")).unwrap()
}
fn trench(case: &Case) -> VirtualTrench {
    let points: Vec<_> = case.polygon.iter().map(vertex).collect();
    let objects: Vec<_> = case.objects.iter().map(vertex).collect();
    let (start, end, width) = centerline(&points, &objects).unwrap();
    let mut t = VirtualTrench::new(case.name.clone(), start, end, width).unwrap();
    t.boundary_3d = points;
    t.objects = objects
        .into_iter()
        .map(|position| TrenchPoint {metadata:Default::default(),
            position,
            role: "object".into(),
            object_name: "LS".into(),
            source_name: "ls".into(),
            attributes: Default::default(),
        })
        .collect();
    t
}
fn check(t: &VirtualTrench, expected: &([Option<f64>; 3], [Option<f64>; 3], f64)) {
    same_vertex(t.start, vertex(&expected.0));
    same_vertex(t.end, vertex(&expected.1));
    close(t.width_meters, expected.2);
}

#[test]
fn automatic_and_absolute_manual_corrections_match_python() {
    for case in cases() {
        let mut t = trench(&case);
        check(&t, &case.automatic);
        recalculate(&mut t).unwrap();
        check(&t, &case.automatic);
        let boundary = t.boundary_3d.clone();
        let objects = serde_json::to_value(&t.objects).unwrap();
        for manual in &case.manual {
            apply_rotation(&mut t, manual.degrees).unwrap();
            check(&t, &manual.expected);
            assert_eq!(
                t.alignment.as_ref().unwrap().rotation_degrees,
                manual.degrees.clamp(-90.0, 90.0)
            );
            assert_eq!(t.boundary_3d, boundary, "{} boundary moved", case.name);
            assert_eq!(
                serde_json::to_value(&t.objects).unwrap(),
                objects,
                "{} objects moved",
                case.name
            );
        }
        recalculate(&mut t).unwrap();
        check(&t, &case.automatic);
        assert_eq!(t.alignment.as_ref().unwrap().rotation_degrees, 0.0);
    }
}

#[test]
fn correction_and_baseline_survive_project_reload() {
    let case = cases().remove(0);
    let mut t = trench(&case);
    recalculate(&mut t).unwrap();
    apply_rotation(&mut t, 25.0).unwrap();
    let mut project = NativeProject {
        virtual_trenches: vec![t],
        ..Default::default()
    };
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("alignment.sleufbase-rust.json");
    save_project(&path, &project).unwrap();
    project = read_project(&path).unwrap();
    let restored = &mut project.virtual_trenches[0];
    check(restored, &case.manual[1].expected);
    apply_rotation(restored, 5.0).unwrap();
    check(restored, &case.manual[0].expected);
    recalculate(restored).unwrap();
    check(restored, &case.automatic);
}

#[test]
fn old_preview_project_without_alignment_remains_readable() {
    let case = cases().remove(0);
    let original = trench(&case);
    let mut value = serde_json::to_value(&original).unwrap();
    value.as_object_mut().unwrap().remove("alignment");
    let mut restored: VirtualTrench = serde_json::from_value(value).unwrap();
    assert!(restored.alignment.is_none());
    // As in Python, a legacy axis becomes the fixed baseline at first correction.
    apply_rotation(&mut restored, 5.0).unwrap();
    check(&restored, &case.manual[0].expected);
    recalculate(&mut restored).unwrap();
    check(&restored, &case.automatic);
}

#[test]
fn invalid_geometry_and_rotation_never_mutate_trench() {
    let mut t = trench(&cases().remove(0));
    for degrees in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        let before = serde_json::to_value(&t).unwrap();
        assert!(apply_rotation(&mut t, degrees).is_err());
        assert_eq!(serde_json::to_value(&t).unwrap(), before);
    }
    t.boundary_3d.clear();
    let before = serde_json::to_value(&t).unwrap();
    assert!(recalculate(&mut t).is_err());
    assert!(apply_rotation(&mut t, 5.0).is_err());
    assert_eq!(serde_json::to_value(&t).unwrap(), before);
    let bad = Vertex {
        x: f64::NAN,
        y: 0.0,
        z: None,
    };
    assert!(centerline(&[bad; 3], &[]).is_err());
    let points: Vec<_> = cases().remove(0).polygon.iter().map(vertex).collect();
    assert!(centerline(&points, &[bad]).is_err());
}

#[test]
fn invalid_saved_baseline_is_rejected() {
    let mut t = trench(&cases().remove(0));
    recalculate(&mut t).unwrap();
    t.alignment.as_mut().unwrap().rotation_degrees = 91.0;
    assert!(t.validate().is_err());
}

#[test]
fn basic_dxf_preserves_boundary_and_corrected_3d_axis() {
    let mut t = trench(&cases().remove(0));
    recalculate(&mut t).unwrap();
    apply_rotation(&mut t, 25.0).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("corrected.dxf");
    sleufbase_rust::write_dxf_with_trenches(&path, &[], &[t.clone()], sleufbase_rust::RULES)
        .unwrap();
    let overlay = sleufbase_rust::dxf_read::load_dxf(&path).unwrap();
    let axis = overlay
        .features
        .iter()
        .find(|f| f.layer == "VIRTUAL_TRENCH_AXIS")
        .unwrap();
    assert_eq!(axis.entity_type, "LINE");
    same_vertex(axis.points[0], t.start);
    same_vertex(axis.points[1], t.end);
    let boundary = overlay
        .features
        .iter()
        .find(|f| f.layer == "VIRTUAL_TRENCH_3D" && f.entity_type == "POLYLINE")
        .unwrap();
    for (original, exported) in t.boundary_3d.iter().zip(&boundary.points) {
        same_vertex(*original, *exported);
    }
}
